import unittest
from retention import retained
class Contract(unittest.TestCase):
    def test_zero(self): self.assertEqual(retained([1,2], 0), [])
    def test_last(self): self.assertEqual(retained([1,2,3], 2), [2,3])
    def test_large(self): self.assertEqual(retained([1], 3), [1])
    def test_invalid(self):
        for value in [-1, True]:
            with self.assertRaises(ValueError): retained([], value)

